// Validate checks m against its grammar and returns the first violation
// as a *diam.AVPError. Required presence is checked on decoded messages
// only: a zero value is a valid encoding, so a hand-built message has
// nothing to check.
func (m *MdtConfiguration) Validate() error {
	if m.decodeErr != nil {
		return m.decodeErr
	}
	if m.excess != nil {
		return m.excess
	}
	if m.decoded && m.seen&(uint64(1)<<0) == 0 {
		return diam.Missing(1623, 10415, "JOB_TYPE")
	}
	if m.AreaScope != nil {
		if err := m.AreaScope.Validate(); err != nil {
			return diam.InGroup(err, 1624)
		}
	}
	for i := range m.MbsfnArea {
		if err := m.MbsfnArea[i].Validate(); err != nil {
			return diam.InGroup(err, 1694)
		}
	}
	return diam.CheckUnknown(m.Unknown)
}

