// Validate checks m against its grammar and returns the first violation
// as a *diam.AVPError. Required presence is checked on decoded messages
// only: a zero value is a valid encoding, so a hand-built message has
// nothing to check.
func (m *CommunicationPatternSet) Validate() error {
	if m.decodeErr != nil {
		return m.decodeErr
	}
	if m.excess != nil {
		return m.excess
	}
	for i := range m.ScheduledCommunicationTime {
		if err := m.ScheduledCommunicationTime[i].Validate(); err != nil {
			return diam.InGroup(err, 3118)
		}
	}
	return diam.CheckUnknown(m.Unknown)
}

